import{F as e,_ as t,f as n,h as r,j as i,n as a}from"./chunks/shared.rYHlazZf.js";var o=JSON.parse(`{"title":"実行時変数の再利用と変更の確認","description":"","frontmatter":{"title":"実行時変数の再利用と変更の確認","docId":"user.automations.variables","translationKey":"user.automations.variables","locale":"ja","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"afcdc4049fccbd2bc17c1040a9f84efb749a8d6291212cfe8809c22728e5c0fb","translationRevision":"e9e11c3ff88ae1095fb685edd00b0b79275ce5f5565951a3dcea713f707ad518","order":40},"headers":[],"relativePath":"ja/user/automations/variables.md","filePath":"ja/user/automations/variables.md","lastUpdated":1795731074000}`),s={name:`ja/user/automations/variables.md`};function c(a,o,s,c,l,u){let d=e(`DemoFrame`);return i(),n(`div`,null,[o[0]||=r(`<h1 id="reuse-and-review-runtime-variables" tabindex="-1">実行時変数の再利用と変更の確認 <a class="header-anchor" href="#reuse-and-review-runtime-variables" aria-label="Permalink to “実行時変数の再利用と変更の確認”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目的と前提条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “目的と前提条件”">​</a></h2><p>共有値を一度変更し、複数のアクションで再利用します。<strong>自動化 → 変数</strong> と、対象の変数操作に対応するホストが必要です。型付き編集や確認を伴う Cloud 操作はホスト機能に応じて表示されます。ローカル保存にアップロードは不要です。</p><h2 id="save-a-local-value" tabindex="-1">ローカル値を保存する <a class="header-anchor" href="#save-a-local-value" aria-label="Permalink to “ローカル値を保存する”">​</a></h2><ol><li><code>showLabel</code> という変数を追加します。キーは英字かアンダースコアで始め、英数字、ドット、アンダースコア、ハイフンを含められます。上限は <code>64</code> 文字です。キーの重複を避けます。</li><li>型付き編集が利用できる場合、テキストを選び <code>夜の配信</code> と入力します。他に数値、真偽値、リスト、シークレットを利用できます。リストは <code>[&quot;赤&quot;, &quot;青&quot;]</code> などの文字列の JSON 配列です。</li><li><strong>グローバル変数を保存</strong> を選びます。リビジョン競合は保存済みコレクションが変わったことを意味するため、再読み込みして変更内容を照合します。</li><li>テンプレート対応のアクション欄で保存値を使います。</li></ol><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{{ globals.showLabel }}: {{ event.user.uniqueId }}</span></span></code></pre></div><ol start="5"><li>ログだけのアクションをテストして展開後のテキストを確認します。<code>showLabel</code> を変更して保存し、もう一度テストします。テンプレートを再インポートしなくても既存アクションは更新された値を使えます。</li></ol><p>テンプレートの <code>params</code> は適用時に置換され、<code>globals</code> は実行時に読まれます。存在しない実行時キーは空文字になるため、送信先や識別子で使う前に綴りを確認してください。イベントのパスは各フィールドの変数候補からトリガーに合うものを選びます。</p><p>条件は一致ごとの値を公開することもできます。フィルターがキャプチャエイリアスを宣言すると、それを満たした値はイベントのアクションのレンダリング中に <code>{{ match.&lt;alias&gt; }}</code>（エイリアスがなければ <code>{{ match.&lt;位置&gt; }}</code>）として使えます。例えば、コメントへの「で始まる」条件に <code>prefix</code> というエイリアスを付けると、ログアクションで <code>{{ match.prefix }}</code> を出力できます。キャプチャは上限付きのプレーンテキストで、実際に一致したフィルターと代替だけが生成し、クールダウンキーは変わりません。</p><p>テンプレート対応フィールドの <strong>+</strong> を押すと <strong>変数を挿入</strong> が開き、右側に正確なパスが表示され、行を選ぶと <code>{{ パス }}</code> がフィールドに追加されます。このイベントのキャプチャも一覧に表示されますが、対応する条件が一致した場合にのみ解決されます。<code>{{ match.&lt;alias&gt; }}</code> を使うには、条件セクションでエイリアスを設定してください（下部の <strong>キャプチャ</strong> ボタンでエイリアス欄を表示します）。設定しない場合は位置 <code>{{ match.&lt;位置&gt; }}</code> を使います。</p><h2 id="review-cloud-changes-separately" tabindex="-1">Cloud の変更は別途確認する <a class="header-anchor" href="#review-cloud-changes-separately" aria-label="Permalink to “Cloud の変更は別途確認する”">​</a></h2><p>変数の <strong>変更</strong> では、対応ホスト上で送信、取得、適用・採用、取り下げを確認付きで実行できます。先にローカル編集を保存し、比較を選び、型と値を確認して方向を明示的に選びます。Cloud 候補の取得とローカル適用は別操作です。共有値の取り下げとローカル行の削除も異なります。</p><p>シークレットや送信禁止の値は比較でマスクされ、この経路では送信できません。制限を回避するためにシークレットを通常テキストに変えないでください。</p><h2 id="expected-result-status-and-recovery" tabindex="-1">期待される結果・提供状況と対処 <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to “期待される結果・提供状況と対処”">​</a></h2><p>ローカル変数と、ホスト機能に応じた確認付き共有を利用できます。ローカル保存で自動アップロードは行われません。不正なキー、型に合わない値、古いリビジョンでは保存できません。強調された欄を修正するか、再読み込みしてから再試行します。アカウントの問題は <a href="./../cloud/account.html">Cloud アカウント</a>、比較の動作は <a href="./../cloud/changes.html">変更</a> を参照してください。</p><p>実際の設定に触れる前にインタラクティブに試せます:</p>`,16),t(d,{scenario:`automation`,locale:`ja`,panel:`automation`,title:`自動化ワークスペースを試す`}),o[1]||=r(`<h2 id="command-line-operations" tabindex="-1">コマンドライン操作 <a class="header-anchor" href="#command-line-operations" aria-label="Permalink to “コマンドライン操作”">​</a></h2><p>このガイドのすべての操作はCLIからも利用できます——オフライン、スクリプト可能、エージェント対応。使用法の行はパーサー構文であり、すべての言語で英語のままです。</p><table tabindex="0"><thead><tr><th>コマンド</th><th>概要</th></tr></thead><tbody><tr><td><code>tiktools globals list</code></td><td>すべてのグローバルキーを一覧表示</td></tr><tr><td><code>tiktools globals get &lt;key&gt;</code></td><td>グローバルを1つ読み取る</td></tr><tr><td><code>tiktools globals set &lt;key&gt; &lt;value&gt;</code></td><td>グローバルを1つ書き込む</td></tr><tr><td><code>tiktools globals delete &lt;key&gt;</code></td><td>グローバルを1つ削除 <strong>破壊的</strong></td></tr></tbody></table><p>規約、JSON出力、破壊的操作のマーカーについては<a href="./../../developer/cli.html">完全なコマンドリファレンス</a>を参照してください。</p>`,4)])}var l=a(s,[[`render`,c]]);export{o as __pageData,l as default};